const services = [
  {title:'Importación y exportación',copy:'De la documentación al despacho. Facilitamos el movimiento de tus mercancías.',icon:'<path d="M5 12h22M22 7l5 5-5 5M27 23H5m5-5-5 5 5 5"/>',detail:'Te acompañamos en la gestión de operaciones de entrada y salida de mercancías, con control de documentación y apoyo en el despacho aduanero.',items:['Importación y exportación definitiva y sus modalidades.','Orientación en regímenes temporales, tránsito y zonas francas.','Revisión de documentos y coordinación de la operación.']},
  {title:'Clasificación arancelaria',copy:'Identificamos la partida de tu mercancía para una gestión precisa y ordenada.',icon:'<rect x="6" y="5" width="21" height="24" rx="2"/><path d="M11 11h11M11 17h4m4 0h3M11 23h4m4 0h3"/>',detail:'Analizamos las características de tu producto para determinar su clasificación dentro del Sistema Arancelario Centroamericano (SAC).',items:['Revisión técnica de la mercancía.','Identificación de partidas y requisitos aplicables.','Orientación para reducir errores en la declaración.']},
  {title:'Asesoría en comercio exterior',copy:'Orientación clara sobre procesos, requisitos y oportunidades comerciales.',icon:'<circle cx="16" cy="16" r="12"/><ellipse cx="16" cy="16" rx="5" ry="12"/><path d="M4 16h24M7 9h18M7 23h18"/>',detail:'Te orientamos sobre los procesos del comercio internacional y la documentación de tu operación, considerando las reglas y preferencias aplicables a tus mercancías.',items:['Revisión de requisitos de importación y exportación.','Orientación sobre acuerdos comerciales y origen.','Asesoría sobre responsabilidades y condiciones de entrega.']},
  {title:'Asesoría legal aduanera',copy:'Acompañamiento especializado para los procedimientos de tu operación.',icon:'<path d="M16 4v24M7 28h18M5 10h22M9 10l-5 11h10L9 10zm14 0-5 11h10l-5-11z"/>',detail:'Brindamos orientación jurídica en procedimientos aduaneros, documentación y recursos administrativos, de acuerdo con las necesidades de cada caso.',items:['Poderes especiales, declaraciones y documentación aduanera.','Orientación en procedimientos de valoración.','Apoyo en recursos de revisión y apelación.']},
  {title:'Trámites especiales',copy:'Apoyo con permisos y gestiones que requieren atención adicional.',icon:'<path d="M9 4h12l5 5v20H6V4h3m12 0v6h5M11 16h10M11 21h10M11 26h6"/>',detail:'Coordinamos gestiones particulares que requieren requisitos, permisos o documentación adicional para tu operación comercial.',items:['Gestiones ante TELCOR y VUCEN.','Orientación en permisos ambientales ante MARENA.','Apoyo en trámites relacionados con el régimen de zonas francas.']},
  {title:'Compramos por ti',copy:'Encuentra lo que buscas. Te ayudamos con la compra y su envío.',icon:'<path d="M3 5h4l4 16h14l4-11H9M12 26a1 1 0 1 0 0 .1M24 26a1 1 0 1 0 0 .1M16 5h9m-4-4 4 4-4 4"/>',detail:'Adquiere tus productos sin ingresar tus datos bancarios directamente en tiendas o aplicaciones. Revisamos contigo el pedido antes de realizar la compra.',items:['Comparte el enlace del producto que deseas.','Revisamos la plataforma y confirmamos los detalles.','Recibe el monto, realiza el depósito y obtén tu comprobante.','Coordinamos el transporte según el servicio elegido.']}
];
document.getElementById('service-grid').innerHTML=services.map((s,i)=>`<article class="service-card"><div class="service-icon"><svg viewBox="0 0 32 32" aria-hidden="true">${s.icon}</svg></div><h3>${s.title}</h3><p>${s.copy}</p><button type="button" data-service="${i}" aria-label="Conocer más sobre ${s.title}">Conocer más <span>↗</span></button></article>`).join('');
const dialog=document.getElementById('service-dialog');
document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>{const s=services[Number(b.dataset.service)];document.getElementById('dialog-title').textContent=s.title;document.getElementById('dialog-copy').textContent=s.detail;const ul=document.getElementById('dialog-list');ul.replaceChildren(...s.items.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));dialog.showModal()}));
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());
document.getElementById('dialog-contact').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const menu=document.querySelector('.menu'),nav=document.getElementById('nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú')}));
const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'});
function calculate(){const weight=document.getElementById('weight'),mode=document.getElementById('mode');const n=Number(weight.value);const valid=weight.value!==''&&Number.isFinite(n)&&n>0&&weight.validity.valid;document.getElementById('total').textContent=valid?money.format(n*Number(mode.value))+' USD':'—';document.getElementById('quote').dataset.valid=String(valid)}
document.getElementById('weight').addEventListener('input',calculate);document.getElementById('mode').addEventListener('change',calculate);document.getElementById('calculator').addEventListener('submit',e=>e.preventDefault());
document.getElementById('quote').addEventListener('click',e=>{const weight=document.getElementById('weight');if(!weight.reportValidity()){e.preventDefault();return}const air=document.getElementById('mode').value==='7';document.getElementById('service').value=air?'Envío aéreo':'Envío marítimo';document.getElementById('message').value=`Hola, quisiera cotizar un envío ${air?'aéreo':'marítimo'} de ${weight.value} lb. El estimado del sitio es ${document.getElementById('total').textContent}. Me gustaría confirmar el costo final y los requisitos.`});
const email='kdeaduanassolutions@gmail.com';
document.getElementById('tracking-form').addEventListener('submit',e=>{e.preventDefault();const number=document.getElementById('tracking-number').value.trim();if(!number)return;window.location.href=`mailto:${email}?subject=${encodeURIComponent('Consulta de seguimiento: '+number)}&body=${encodeURIComponent('Hola, quisiera consultar el estado de mi envío. Número de seguimiento: '+number)}`});
document.getElementById('contact-form').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('name').value.trim(),reply=document.getElementById('email').value.trim(),service=document.getElementById('service').value,message=document.getElementById('message').value.trim();if(!name||!message)return;window.location.href=`mailto:${email}?subject=${encodeURIComponent('Consulta: '+service)}&body=${encodeURIComponent(`Nombre: ${name}\nCorreo de contacto: ${reply}\nServicio: ${service}\n\n${message}`)}`;document.getElementById('form-status').textContent='Consulta preparada. Completa el envío en tu aplicación de correo. Si no se abre, escríbenos directamente a '+email+'.'});
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+entry.target.id))}})},{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));
calculate();
